{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 1000",
      "description": "The size of the array n must be between 1 and 1000 inclusive."
    },
    {
      "id": "P2",
      "expression": "all(1 <= len(arr[i]) <= 1000 for i in range(n))",
      "description": "Each string in arr must have a length between 1 and 1000 inclusive."
    },
    {
      "id": "P3",
      "expression": "1 <= len(str) <= 1000",
      "description": "The string str must have a length between 1 and 1000 inclusive."
    },
    {
      "id": "P4",
      "expression": "1 <= k <= 1000",
      "description": "The integer k must be between 1 and 1000 inclusive."
    },
    {
      "id": "P5",
      "expression": "all(arr[i].islower() for i in range(n))",
      "description": "All characters in each string of arr must be lowercase English alphabets."
    },
    {
      "id": "P6",
      "expression": "str.islower()",
      "description": "All characters in the string str must be lowercase English alphabets."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "return_value == sum(arr[i][:k] == str[:k] for i in range(n))",
      "description": "The return value must be the count of strings in arr whose prefix of length k matches the k-length prefix of str."
    }
  ],
  "invariants": []
}
